type WorldStateHandle = {
  entities: Record<string, string>;
};

const INITIAL_STATE: WorldStateHandle = {
  entities: { Fen: "pex" },
};

function copyState(state: WorldStateHandle): WorldStateHandle {
  return { entities: { ...state.entities } };
}

export const protocol: WorldProtocol<WorldStateHandle> = {
  reset(): WorldStateHandle {
    return copyState(INITIAL_STATE);
  },

  applyOperation(state, operationDisplayName) {
    const currentState = state.entities.Fen;

    if (operationDisplayName === "advanceFen") {
      if (currentState !== "pex") {
        return {
          success: false,
          error: "advanceFen can only be applied when Fen is pex",
        };
      }

      const newState = copyState(state);
      newState.entities.Fen = "dor";
      return { success: true, newState };
    }

    if (operationDisplayName === "recoverFen") {
      if (currentState !== "dor") {
        return {
          success: false,
          error: "recoverFen can only be applied when Fen is dor",
        };
      }

      const newState = copyState(state);
      newState.entities.Fen = "pex";
      return { success: true, newState };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state, entityDisplayName) {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state) {
    return { ...state.entities };
  },
};
